entries[326846] = { ["name"] = "Sünde zerstreuen", ["text"] = "Sofort\nInquisitor Sigar zerstreut die Sünde einer zufälligen Manifestation des Neids, was Spielercharakteren innerhalb von 4 Metern 3636674 Schattenschaden zufügt und einen Bereich von ' Zerstreute Sünde ' erschafft, der 1 Min. lang anhält.\nSpielercharaktere innerhalb des Effektbereichs von ' Zerstreute Sünde ' erleiden alle 1 Sek. 3879119 Schattenschaden." }
