entries[327087] = { ["name"] = "Rune der Apokalypse", ["text"] = "Euer Ghul ruft beim Einsatz von 'Klaue' zusätzliche Effekte hervor.\n\nTod: Verringert die erhaltene Heilung um 5%.\nKrieg: Erhöht den erlittenen Schaden um 4%.\nHungersnot: Verringert den dem Todesritter zugefügten Schaden um 5%.\nPestilenz: Verlangsamt das Ziel um 15% und verursacht (150% der Angriffskraft) Schattenschaden im Verlauf von 327093d" }
