entries[327089] = { ["name"] = "Fütterungszeit", ["text"] = "Unbegrenzte Reichweite\nSofort\nDenathrius markiert zufällige Spielercharaktere und schlägt 5 Sek. später zu. Fügt Spielercharakteren innerhalb von 4 Metern um jedes Ziel 47405 körperlichen Schaden zu und heilt Denathrius um 150% dieses Werts." }
entries[327090] = { ["name"] = "Konstrukt wiederherstellen", ["text"] = "Wirken in 3 sek.\nReagenzien:\nFormbares Fleisch\nHolt ein kürzlich verstorbenes oder verschwundenes Konstrukt auf das Schlachtfeld zurück." }
entries[327091] = { ["name"] = "Monströse Unterstützung", ["text"] = "Wirken in 3 sek.\nReagenzien:\nFormbares Fleisch (5), Hochwertige Teile\nEin Signalhorn, um Emeni zu rufen, damit sie Euch für kurze Zeit im Kampf unterstützt." }
